script.content:
set -euo pipefail;
TITLE="$1"; BODY="${2-}"; BASE="${3-main}"; DRAFT_FLAG="${4-false}";
command -v gh >/dev/null 2>&1 || { echo 'gh is required for /pr'; exit 1; }
# Ensure branch has an upstream and push
if ! git rev-parse --abbrev-ref --symbolic-full-name @{u} >/dev/null 2>&1; then
  CURRENT_BRANCH=$(git rev-parse --abbrev-ref HEAD);
  git push -u origin "$CURRENT_BRANCH";
fi;
# Generate body from diff if not provided
if [ -z "$BODY" ]; then
  BODY=$(git log --oneline -n 5; echo; echo '## Diff'; echo '```'; git diff --stat "$BASE"...HEAD || true; echo '```');
fi;
# Create PR (or view existing)
if gh pr view --json url >/dev/null 2>&1; then
  echo 'PR already exists:'; gh pr view --json url -q .url;
else
  if [ "$DRAFT_FLAG" = "true" ]; then DRAFT_OPT=--draft; else DRAFT_OPT=; fi;
  gh pr create --base "$BASE" --title "$TITLE" --body "$BODY" $DRAFT_OPT --fill;
  gh pr view --json url -q .url;
fi

set -euo pipefail; MSG="$1";
# Stage all by default if nothing staged
if [ -z "$(git diff --name-only --cached)" ]; then git add -A; fi;
# Commit via heredoc to preserve newlines
COMMIT_MSG=$(cat <<EOF
$MSG
EOF
);
if git commit -m "$COMMIT_MSG"; then
  echo 'Committed successfully.';
else
  echo 'No changes to commit or commit failed.';
fi;

# Show concise status
git --no-pager log -1 --stat --oneline;

set -euo pipefail;
echo '## Summary of changes';
git --no-pager diff --stat HEAD || true;
echo; echo '## Files changed';
git --no-pager diff --name-only HEAD || true;
echo; echo '## Recent commits';
git --no-pager log -5 --oneline || true;

set -euo pipefail; SUITE="${1-all}";
if [ ! -x scripts/test-e2e.sh ]; then echo 'scripts/test-e2e.sh not found'; exit 1; fi;
./scripts/test-e2e.sh "$SUITE"

set -euo pipefail; command -v gh >/dev/null 2>&1 || { echo 'gh is required for /pr-ready'; exit 1; }; TITLE="${1-}"; BRANCH=$(git rev-parse --abbrev-ref HEAD);
if ! git rev-parse --abbrev-ref --symbolic-full-name @{u} >/dev/null 2>&1; then git push -u origin "$BRANCH"; else git push; fi;
if gh pr view --json url >/dev/null 2>&1; then echo PR: $(gh pr view --json url -q .url); else [ -n "$TITLE" ] || TITLE="$BRANCH"; gh pr create --title "$TITLE" --body "Auto-created via /pr-ready" --fill; echo PR: $(gh pr view --json url -q .url); fi;
echo; echo 'Latest runs:'; gh run list --branch "$BRANCH" --limit 3

set -euo pipefail; command -v kubectl >/dev/null 2>&1 || { echo 'kubectl is required for /k8s-deploy'; exit 1; }; PATH_ARG="${1-k8s/manifests}"; NS="${2-}";
if [ ! -d "$PATH_ARG" ]; then echo "Path not found: $PATH_ARG"; exit 1; fi;
if [ -n "$NS" ]; then NS_OPT="-n $NS"; else NS_OPT=; fi;
kubectl apply $NS_OPT -f "$PATH_ARG"

set -euo pipefail; command -v kubectl >/dev/null 2>&1 || { echo 'kubectl is required for /k8s-logs'; exit 1; }; DEP="$1"; NS="${2-}"; if [ -n "$NS" ]; then NS_OPT="-n $NS"; else NS_OPT=; fi;
PODS=$(kubectl get pods $NS_OPT -l app="$DEP" -o jsonpath='{.items[*].metadata.name}' 2>/dev/null || true);
if [ -z "$PODS" ]; then PODS=$(kubectl get pods $NS_OPT -l app.kubernetes.io/name="$DEP" -o jsonpath='{.items[*].metadata.name}' 2>/dev/null || true); fi;
if [ -z "$PODS" ]; then echo 'No pods found for label app or app.kubernetes.io/name'; exit 1; fi;
for p in $PODS; do echo ==== $p ====; kubectl logs $NS_OPT --tail=200 -f "$p" & done; wait

set -euo pipefail; command -v yq >/dev/null 2>&1 || { echo 'yq is required for /workflow-audit'; exit 1; }; DIR=.github/workflows; [ -d $DIR ] || { echo 'No workflows directory'; exit 0; };
for f in $DIR/*.yml $DIR/*.yaml; do [ -e "$f" ] || continue; echo "== $f ==";
# Check basic keys
if ! yq e '.on' "$f" >/dev/null 2>&1; then echo '  - Missing on: triggers'; fi;
if ! yq e '.jobs' "$f" >/dev/null 2>&1; then echo '  - Missing jobs:'; fi;
# Empty steps detection
STEPS=$(yq e '.jobs.*.steps | length' "$f" 2>/dev/null || echo 0); if [ "$STEPS" = "0" ]; then echo '  - No steps defined in at least one job'; fi;
NAME=$(yq e '.name' "$f"); if [ "$NAME" = "null" ] || [ -z "$NAME" ]; then echo '  - Missing name'; fi; done
